import json

from messaging_client import get_sns_client


def dead_letter_event(payload, config=None):
    config = config or {}
    sns_client = get_sns_client(config.get("region"))
    response = sns_client.publish(
        TopicArn=config["dead_letter_topic_arn"],
        Message=json.dumps(payload["event"]),
        MessageAttributes={
            "reason": {
                "DataType": "String",
                "StringValue": payload.get("reason", "Unknown error")
            }
        }
    )
    return {"message_id": response["MessageId"], "status": "dead_lettered"}

import json

from messaging_client import get_sns_client
from messaging_models import BatchPublishRequest, PublishResponse


def batch_publish(batch_request: BatchPublishRequest, config=None):
    config = config or {}
    sns_client = get_sns_client(config.get("region"))
    results = []
    for message_payload in batch_request.messages:
        response = sns_client.publish(
            TopicArn=batch_request.topic_arn,
            Message=json.dumps(message_payload["event"]),
            MessageAttributes={
                "message_id": {
                    "DataType": "String",
                    "StringValue": message_payload.get("id", "")
                }
            }
        )
        results.append(PublishResponse(message_id=response["MessageId"]))
    return {"published_messages": [res.message_id for res in results]}

from messaging_client import get_comprehend_client
from messaging_models import MessageSummary


def summarize_message(message_id: str, text_content: str, config=None):
    config = config or {}
    comprehend_client = get_comprehend_client(config.get("region"))
    try:
        # For summarization, Comprehend doesn't have a direct 'summarize' API in a simple call.
        # A common approach is to extract key phrases or entities to get a 'summary'.
        # For a true summary, one might use a more advanced NLP service or custom model.
        # Here, we'll use key phrase detection as a form of summarization.
        response = comprehend_client.detect_key_phrases(Text=text_content, LanguageCode="en")
        key_phrases = [phrase['Text'] for phrase in response['KeyPhrases']]
        summary_text = "; ".join(key_phrases)
        if not summary_text:
            summary_text = "No key phrases found for summarization."
    except Exception as e:
        summary_text = f"Error summarizing message: {str(e)}"

    return MessageSummary(message_id=message_id, summary=summary_text)

from messaging_client import get_comprehend_client
from messaging_models import MessageSafetyResult


def check_message_safety(message_id: str, text_content: str, config=None):
    config = config or {}
    comprehend_client = get_comprehend_client(config.get("region"))
    is_safe = True
    details = {}

    try:
        # Check for sentiment (e.g., if it's overly negative, might indicate unsafe content)
        sentiment_response = comprehend_client.detect_sentiment(Text=text_content, LanguageCode="en")
        sentiment = sentiment_response["Sentiment"]
        details["sentiment"] = sentiment
        if sentiment in ["NEGATIVE", "MIXED"]:
            is_safe = False
            details["reason"] = details.get("reason", []) + ["Negative/Mixed sentiment detected"]

        # Check for PII (Personally Identifiable Information)
        pii_response = comprehend_client.detect_pii_entities(Text=text_content, LanguageCode="en")
        if pii_response["Entities"]:
            is_safe = False
            details["pii_entities_count"] = len(pii_response["Entities"])
            details["reason"] = details.get("reason", []) + ["PII detected"]

    except Exception as e:
        is_safe = False
        details["error"] = str(e)
        details["reason"] = details.get("reason", []) + ["Error during safety check"]

    return MessageSafetyResult(message_id=message_id, is_safe=is_safe, details=details)

from messaging_client import get_translate_client
from messaging_models import TranslatedPayload


def translate_payload(message_id: str, text_content: str, target_language: str, source_language: str = "auto", config=None):
    config = config or {}
    translate_client = get_translate_client(config.get("region"))
    translated_text = ""
    actual_source_language = source_language

    try:
        response = translate_client.translate_text(
            Text=text_content,
            SourceLanguageCode=source_language,
            TargetLanguageCode=target_language
        )
        translated_text = response["TranslatedText"]
        actual_source_language = response.get("SourceLanguageCode", source_language)
    except Exception as e:
        translated_text = f"Error translating message: {str(e)}"

    return TranslatedPayload(
        message_id=message_id,
        translated_text=translated_text,
        source_language=actual_source_language,
        target_language=target_language
    )

